function localParts(tz,date){const p={};new Intl.DateTimeFormat("en-GB",{timeZone:tz,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(date).forEach(x=>{p[x.type]=x.value;});return p;}
function localISO(tz,date){const p=localParts(tz,date);return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`;}
function localClock(tz,date){const p=localParts(tz,date);return `${p.hour}:${p.minute}`;}
function fmtDur(m){return m>=60?`${Math.floor(m/60)}h ${String(m%60).padStart(2,"0")}m`:`${m}m`;}
function sunInfo(w,tz){if(!w||!w.daily)return null;const now=localISO(tz,new Date()),day=now.slice(0,10),i=Math.max(0,w.daily.time.indexOf(day)),rise=w.daily.sunrise[i],set=w.daily.sunset[i],ms=s=>Date.parse(s+":00Z"),n=ms(now);let next,kind;if(n<ms(rise)){next=rise;kind="Sunrise";}else if(n<ms(set)){next=set;kind="Sunset";}else{next=w.daily.sunrise[i+1]||rise;kind="Sunrise";}return{kind,time:next.slice(11),mins:Math.max(0,Math.round((ms(next)-n)/60000))};}
