function clearDestinationFilters(){ $("#destinationSearch").value="";activeCountry="All countries";activeCategory="All experiences";renderCountryTray();renderCategoryFilters();renderDestinations();}
function validateBooking(){clearErrors();const values={fullName:$("#fullName").value.trim(),email:$("#email").value.trim(),phone:$("#phone").value.trim(),country:$("#travelerCountry").value.trim(),destination:$("#bookingDestination").value,plan:$("#packageType").value,start:$("#travelStart").value,end:$("#travelEnd").value,adults:$("#adults").value,children:$("#children").value,accommodation:$("#accommodation").value,activities:$$('#activityChoices input:checked').map(input=>input.value),contact:$("input[name=preferredContact]:checked")?.value||""};let first=null;const add=(id,message)=>{const element=setError(id,message);if(!first&&element)first=element;};if(values.fullName.length<2)add("fullName","Enter your full name.");if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email))add("email","Enter a valid email address.");if((values.contact==="WhatsApp"||values.phone)&&values.phone.replace(/\D/g,"").length<7)add("phone","Enter your WhatsApp number, with country code.");if(!qOff("travelerCountry")&&values.country.length<2)add("travelerCountry","Enter your country.");if(!values.destination)add("bookingDestination","Choose a destination.");if(!values.plan)add("packageType","Choose a trip style.");if(!values.start)add("travelStart","Choose a start date.");if(!values.end)add("travelEnd","Choose a return date.");if(values.start&&values.end&&values.end<values.start)add("travelEnd","Return date must be on or after the start date.");if(!values.adults||Number(values.adults)<1||Number(values.adults)>30)add("adults","Enter at least 1 adult.");if(!qOff("children")&&(values.children===""||Number(values.children)<0||Number(values.children)>30))add("children","Enter 0 or more children.");if(!qOff("accommodation")&&!values.accommodation)add("accommodation","Choose an accommodation preference.");if(!qOff("activities")&&!values.activities.length){$("#activityChoices").setAttribute("aria-invalid","true");$("#activitiesError").textContent="Choose at least one activity or select ‘Not sure yet’.";first ||= $("#activityChoices input");}if(!values.contact){$$('[name="preferredContact"]').forEach(r=>r.setAttribute("aria-invalid","true"));$("#preferredContactError").textContent="Choose how you prefer to be contacted.";first ||= $("input[name=preferredContact]");}values.custom=[];customAnswers().forEach(c=>{const el=document.getElementById(c.id);if(el)el.removeAttribute("aria-invalid");const er=document.getElementById(c.id+"Error");if(er)er.textContent="";if(c.q.required&&!c.answer){const e=setError(c.id,"Please answer this question.");if(!first&&e)first=e;}else if(c.answer)values.custom.push([c.q.label,c.answer]);});
if(first){first.focus();first.scrollIntoView({behavior:"smooth",block:"center"});return null;}return values;}
function newRef(){return("B"+Date.now().toString(36)+Math.random().toString(36).slice(2,6)).toUpperCase().replace(/[^A-Z0-9]/g,"").slice(0,13);}
function buildRow(v,ref){const cut=(t,n)=>String(t==null?"":t).slice(0,n),adults=Number(v.adults)||1,kids=qOff("children")?0:(Number(v.children)||0),nights=v.start&&v.end?Math.max(0,Math.round((Date.parse(v.end)-Date.parse(v.start))/864e5)):null,month=v.start?new Date(v.start+"T12:00:00").toLocaleDateString("en-US",{month:"long"}):"";
  const notes=[!qOff("travelerCountry")?`Country: ${v.country}`:"",`Adults: ${adults}`+(qOff("children")?"":` · Children: ${kids}`),!qOff("accommodation")?`Accommodation: ${v.accommodation}`:"",!qOff("budget")?`Budget: ${$("#budget").value.trim()||"Not specified"}`:"",!qOff("activities")?`Activities: ${v.activities.join(", ")}`:"",...(v.custom||[]).map(c=>`${c[0]}: ${c[1]}`),!qOff("specialRequests")?`Requests: ${$("#specialRequests").value.trim()||"None"}`:""].filter(Boolean).join("\n");
  return{id:ref,name:cut(v.fullName,120),email:cut(v.email,254),phone:cut(v.phone,40),contact:v.contact==="WhatsApp"?"WhatsApp":"Email",notes:cut(notes,4000),destinations:[cut(v.destination,120)],month:cut(month,20),start_date:v.start||null,end_date:v.end||null,travellers:Math.min(200,Math.max(1,adults+kids)),nights,style:cut(planLabel(v.plan),20),trip_id:selectedTrip&&selectedTrip.tripId?selectedTrip.tripId:null,trip_title:cut(selectedTrip?selectedTrip.title:"",160),trip_price_usd:selectedTrip&&selectedTrip.priceUSD>0?selectedTrip.priceUSD:null};}
async function sendBooking(row){const ctl=new AbortController(),to=setTimeout(()=>ctl.abort(),15000);try{const r=await fetch(SB_URL+"/rest/v1/bookings",{method:"POST",signal:ctl.signal,headers:{"Content-Type":"application/json",Prefer:"return=minimal",apikey:SB_KEY},body:JSON.stringify(row)});if(r.ok||r.status===409)return{ok:true};let j={};try{j=await r.json();}catch(e){}return{ok:false,refused:r.status>=400&&r.status<500&&r.status!==408&&r.status!==429,message:j&&j.message?String(j.message):""};}catch(e){return{ok:false};}finally{clearTimeout(to);}}
function queueBooking(row){try{const q=(JSON.parse(localStorage.getItem(OUTBOX_KEY))||[]).filter(x=>x.id!==row.id);q.push(Object.assign({},row,{_at:Date.now()}));localStorage.setItem(OUTBOX_KEY,JSON.stringify(q.slice(-10)));}catch(e){}}
async function flushOutbox(){let q=[];try{q=JSON.parse(localStorage.getItem(OUTBOX_KEY))||[];}catch(e){}if(!q.length)return;const keep=[];for(const rec of q){if(Date.now()-(rec._at||0)>7*864e5)continue;const row=Object.assign({},rec);delete row._at;const r=await sendBooking(row);if(!r.ok&&!r.refused)keep.push(rec);}try{localStorage.setItem(OUTBOX_KEY,JSON.stringify(keep));}catch(e){}}
function showThanks(first,contact,ref,saved){$("#thanksTitle").textContent=`Thank you${first?", "+first:""}!`;$("#thanksMsg").textContent=saved?`We have your request. Our team will contact you within 24 hours by ${contact==="WhatsApp"?"WhatsApp":"email"}.`:`Your request is saved on this device and will be sent as soon as you are back online. Once it is received, our team will contact you within 24 hours.`;$("#thanksRef").textContent=`Reference: ${ref}`;const d=$("#thanksDialog");if(!d.open)d.showModal();}
