$("#categoryFilters").addEventListener("click",event=>{const button=event.target.closest("[data-category]");if(!button)return;activeCategory=button.dataset.category;renderCategoryFilters();renderDestinations();});$("#destinationGrid").addEventListener("click",event=>{const explore=event.target.closest("[data-explore]");const book=event.target.closest("[data-book-destination]");if(explore)openDestination(explore.dataset.explore,explore);else if(book)bookDestination(destinationBySlug(book.dataset.bookDestination));if(event.target.closest("[data-clear-filters]"))clearDestinationFilters();});

$("#planGrid").addEventListener("click",event=>{const button=event.target.closest("[data-plan]");if(button)bookDestination(null,button.dataset.plan);});$("#offerFilters").addEventListener("click",event=>{const button=event.target.closest("[data-offer-filter]");if(!button)return;activeOffer=button.dataset.offerFilter;renderOfferFilters();renderOffers();});$("#offerGrid").addEventListener("click",event=>{const det=event.target.closest("[data-trip-details]");if(det){openTrip(det.dataset.tripDetails);return;}const button=event.target.closest("[data-plan]");if(button)bookDestination(null,button.dataset.plan,offers.find(o=>o.id===button.dataset.trip)||null);});
$("#destinationDialog").addEventListener("click",event=>{if(event.target===$("#destinationDialog"))$("#destinationDialog").close();});$("#dialogClose").addEventListener("click",()=>$("#destinationDialog").close());$("#dialogBook").addEventListener("click",()=>{const item=currentDialogDestination;$("#destinationDialog").close();if(item)bookDestination(item,"day_trips");});$("#destinationDialog").addEventListener("close",()=>{const trigger=$('[data-restore-focus="true"]');if(trigger){trigger.removeAttribute("data-restore-focus");trigger.focus({preventScroll:true});}});
$("#bookingDestination").addEventListener("change",()=>{updateActivities();clearErrors();$("#bookingNotice").textContent="";});$("#packageType").addEventListener("change",updateSummary);["travelStart","travelEnd","adults","children"].forEach(id=>document.getElementById(id).addEventListener("input",updateSummary));$("#specialRequests").addEventListener("input",()=>$("#charCount").textContent=`${$("#specialRequests").value.length} / 3000`);$("#activityChoices").addEventListener("change",()=>{const picks=$$("input:checked",$("#activityChoices"));$("#activitiesError").textContent=picks.length?"":"Choose at least one activity or select ‘Not sure yet’.";$("#activityChoices").removeAttribute("aria-invalid");});
$("#bookingForm").addEventListener("input",event=>{if(event.target.matches("input,select,textarea"))updateSummary();});$("#bookingForm").addEventListener("submit",async event=>{event.preventDefault();const values=validateBooking();if(!values)return;const btn=event.target.querySelector(".submit-button"),label=btn.innerHTML;btn.disabled=true;btn.textContent="Sending…";$("#bookingNotice").textContent="";const ref=newRef(),row=buildRow(values,ref),res=await sendBooking(row);btn.disabled=false;btn.innerHTML=label;
  if(res.ok){showThanks(values.fullName.split(/\s+/)[0],values.contact,ref,true);event.target.reset();selectedTrip=null;$("#summaryTripRow").hidden=true;updateActivities();updateSummary();$("#charCount").textContent="0 / 3000";}
  else if(res.refused&&res.message){$("#bookingNotice").textContent=res.message;}
  else if(res.refused){$("#bookingNotice").textContent="We could not accept this request. Please check your details, or email travelcuraters@gmail.com.";}
  else{queueBooking(row);showThanks(values.fullName.split(/\s+/)[0],values.contact,ref,false);event.target.reset();selectedTrip=null;updateActivities();updateSummary();}});
