let currentTrip=null;
function openTrip(id){const o=offers.find(x=>x.id===id);if(!o)return;currentTrip=o;const img=$("#tripImage");img.src=o.image||"";img.alt=o.title;img.hidden=!o.image;$("#tripMeta").textContent=o.eyebrow;$("#tripTitle").textContent=o.title;$("#tripAvail").textContent=[o.availability,o.status].filter(Boolean).join(" · ");$("#tripDesc").textContent=o.details||o.description||"";$("#tripPrice").textContent=priceText(o.priceUSD);$("#tripPer").hidden=!(o.priceUSD>5);$("#tripDialog").showModal();}
