/* ---- announcement pop-up ---- */
function annHash(a){const t=[a.announcement_title,a.announcement_text,a.announcement_link].join("|");let h=0;for(let i=0;i<t.length;i++)h=(h*31+t.charCodeAt(i))|0;return String(h);}
function maybeAnnounce(){if(annDone||!announce||!announce.announcement_on||!(announce.announcement_title||announce.announcement_text))return;const key=annHash(announce);let off="",seen="";try{off=localStorage.getItem("curaters.ann.off");seen=sessionStorage.getItem("curaters.ann.seen");}catch(e){}if(off===key||seen===key)return;annDone=true;
  $("#annTitle").textContent=announce.announcement_title||"Good news from Curaters";$("#annText").textContent=announce.announcement_text||"";$("#annText").hidden=!announce.announcement_text;
  const go=$("#annGo"),link=announce.announcement_link||"#book";go.href=link;go.textContent=announce.announcement_link?"Learn more":"Plan a trip";const ext=/^https?:/i.test(link);go.target=ext?"_blank":"";go.rel=ext?"noopener noreferrer":"";const arrow=document.createElement("span");arrow.setAttribute("aria-hidden","true");arrow.textContent=" ↗";go.appendChild(arrow);
  window.setTimeout(()=>{const d=$("#announceDialog");if(d&&!d.open&&!$$("dialog[open]").length){d.showModal();try{sessionStorage.setItem("curaters.ann.seen",key);}catch(e){}}},1200);}
$("#annClose").addEventListener("click",()=>$("#announceDialog").close());$("#announceDialog").addEventListener("click",e=>{if(e.target===$("#announceDialog"))$("#announceDialog").close();});
$("#annGo").addEventListener("click",()=>$("#announceDialog").close());
$("#annSkip").addEventListener("click",()=>{try{localStorage.setItem("curaters.ann.off",annHash(announce||{}));}catch(e){}$("#announceDialog").close();});
